     7	public class CorporateRatePlan extends RatePlan {
     8	    private static final Map<String, BigDecimal> CORPORATE_DISCOUNTS = Map.of(
     9	        "TECNOSUL", BigDecimal.valueOf(0.12),
    10	        "AGROVALE", BigDecimal.valueOf(0.18),
    11	        "FARMAVIDA", BigDecimal.valueOf(0.25)
    12	    );
    13	
    14	    private String companyCode;
    15	    private BigDecimal discountRate;
    16	
    17	    public CorporateRatePlan() {
    18	        super("CORPORATE");
    19	    }
    20	
    21	    public void setCompanyCode(String companyCode) {
    22	        this.companyCode = companyCode;
    23	        this.discountRate = CORPORATE_DISCOUNTS.get(companyCode);
    24	    }
    25	
    26	    public String getCompanyCode() {
    27	        return companyCode;
    28	    }
    29	
    30	    @Override
    31	    public void validate(int roomCapacity, int guests, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    32	        if (companyCode == null || !CORPORATE_DISCOUNTS.containsKey(companyCode)) {
    33	            throw new ValidationException("INVALID_REQUEST",
    34	                "Código de empresa inválido");
    35	        }
    36	        if (guests < 1 || guests > roomCapacity) {
    37	            throw new ValidationException("CAPACITY_EXCEEDED",
    38	                "Número de hóspedes inválido para a capacidade do quarto");
    39	        }
    40	        setCompanyCode(companyCode);
    41	    }
    42	
    43	    @Override
    44	    public BigDecimal calculateSubtotal(BigDecimal nightlyRate, int nights, LocalDate checkIn, LocalDate checkOut, Room.RoomType roomType) {
    45	        BigDecimal total = BigDecimal.ZERO;
    46	        LocalDate current = checkIn;
    47	        while (current.isBefore(checkOut)) {
    48	            BigDecimal rate = PricingUtils.getNightlyRateWithSeason(nightlyRate, current);
    49	            total = total.add(rate);
    50	            current = current.plusDays(1);
    51	        }
    52	        return total;
    53	    }
    54	
    55	    @Override
    56	    public BigDecimal calculateDiscount(BigDecimal subtotal) {
    57	        return PricingUtils.roundHalfEven(subtotal.multiply(discountRate));
    58	    }
    59	
    60	    @Override
    61	    public BigDecimal calculateRefund(Reservation reservation) {
    62	        if (reservation.getStatus() == Reservation.ReservationStatus.PENDING) {
    63	            return BigDecimal.ZERO;
    64	        }
    65	        return reservation.getAmountPaid();
    66	    }
    67	}
