=== src/main/java/com/pousada/models/PricingUtils.java
     1	package com.pousada.models;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	
     7	public class PricingUtils {
     8	    private static final int SCALE = 2;
     9	
    10	    public static BigDecimal roundHalfEven(BigDecimal value) {
    11	        return value.setScale(SCALE, RoundingMode.HALF_EVEN);
    12	    }
    13	
    14	    public static boolean isHighSeason(LocalDate date) {
    15	        int month = date.getMonthValue();
    16	        int day = date.getDayOfMonth();
    17	
    18	        if (month == 7) return true;
    19	        if (month == 12 && day >= 15) return true;
    20	        if (month == 1 || month == 2) return true;
    21	
    22	        return false;
    23	    }
    24	
    25	    public static BigDecimal getNightlyRateWithSeason(BigDecimal baseRate, LocalDate date) {
    26	        BigDecimal rate = baseRate;
    27	        if (isHighSeason(date)) {
    28	            rate = rate.multiply(BigDecimal.valueOf(1.2));
    29	        }
    30	        return roundHalfEven(rate);
    31	    }
    32	
    33	    public static int countNights(LocalDate checkIn, LocalDate checkOut) {
    34	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    35	    }
    36	
    37	    public static boolean isWeekend(LocalDate date) {
    38	        return date.getDayOfWeek().getValue() >= 5;
    39	    }
    40	
    41	    public static LocalDate getFollowingSunday(LocalDate friday) {
    42	        if (friday.getDayOfWeek().getValue() != 5) {
    43	            throw new IllegalArgumentException("Deve ser uma sexta-feira");
    44	        }
    45	        return friday.plusDays(2);
    46	    }
    47	}
