    20	        if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY) {
    21	            throw new ValidationException("INVALID_REQUEST",
    22	                "Pacote de fim de semana deve começar na sexta-feira");
    23	        }
    24	
    25	        if (checkOut.getDayOfWeek() != DayOfWeek.SUNDAY ||
    26	            !checkOut.equals(checkIn.plusDays(2))) {
    27	            throw new ValidationException("INVALID_REQUEST",
    28	                "Pacote de fim de semana deve ser de sexta a domingo (2 noites)");
    29	        }
