    33	                "Número de hóspedes inválido para a capacidade do quarto");
    34	        }
    35	    }
    36	
    37	    @Override
    38	    public BigDecimal calculateSubtotal(BigDecimal nightlyRate, int nights, LocalDate checkIn, LocalDate checkOut, Room.RoomType roomType) {
    39	        return switch (roomType) {
    40	            case STANDARD -> standardPrice;
