    53	        if (reservation.getStatus() == Reservation.ReservationStatus.PENDING) {
    54	            return BigDecimal.ZERO;
    55	        }
    56	        return PricingUtils.roundHalfEven(reservation.getAmountPaid().multiply(BigDecimal.valueOf(0.5)));
