    53	        sb.append("Quarto: ").append(receipt.getRoomNumber())
    54	          .append(" (").append(receipt.getRoomType()).append(")\n");
    55	        sb.append("Entrada: ").append(formatDate(receipt.getCheckIn()))
    56	          .append(" | Saída: ").append(formatDate(receipt.getCheckOut()))
    57	          .append(" | ").append(receipt.getNights()).append(receipt.getNights() == 1 ? " diária" : " diárias").append("\n");
    58	        sb.append("Diárias: ").append(formatMoney(receipt.getSubtotal())).append("\n");
