   130	    public boolean isRoomAvailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
   131	        LocalDate current = checkIn;
   132	        while (current.isBefore(checkOut)) {
   133	            for (Reservation reservation : reservations.values()) {
   134	                if (reservation.getRoomNumber() == roomNumber &&
   135	                    reservation.getStatus() != Reservation.ReservationStatus.CANCELLED) {
   136	                    if (!current.isBefore(reservation.getCheckIn()) &&
   137	                        current.isBefore(reservation.getCheckOut())) {
   138	                        return false;
   139	                    }
   140	                }
   141	            }
   142	            current = current.plusDays(1);
   143	        }
   144	        return true;
