   151	                reservation.getStatus() != Reservation.ReservationStatus.CANCELLED &&
   152	                (reservation.getStatus() == Reservation.ReservationStatus.CONFIRMED ||
   153	                 reservation.getStatus() == Reservation.ReservationStatus.CHECKED_IN ||
   154	                 reservation.getStatus() == Reservation.ReservationStatus.CHECKED_OUT)) {
   155	                if (!date.isBefore(reservation.getCheckIn()) && date.isBefore(reservation.getCheckOut())) {
   156	                    result.add(reservation);
