   168	                (reservation.getStatus() == Reservation.ReservationStatus.CONFIRMED ||
   169	                 reservation.getStatus() == Reservation.ReservationStatus.CHECKED_IN ||
   170	                 reservation.getStatus() == Reservation.ReservationStatus.CHECKED_OUT ||
   171	                 reservation.getStatus() == Reservation.ReservationStatus.CANCELLED)) {
   172	                result.add(reservation);
   173	            }
   174	        }
   175	        return result;
