178	    private void validateBasicInput(int roomNumber, String checkInStr, String checkOutStr, int guests) {
179	        if (guests < 1) {
180	            throw new ApiException("INVALID_REQUEST", "Número de hóspedes inválido", 400);
181	        }
182	
183	        try {
184	            LocalDate.parse(checkInStr, dateFormatter);
185	            LocalDate.parse(checkOutStr, dateFormatter);
186	        } catch (Exception e) {
187	            throw new ApiException("INVALID_REQUEST", "Formato de data inválido", 400);
188	        }
189	    }
190	
191	    private void validateDateRange(LocalDate checkIn, LocalDate checkOut) {
192	        if (!checkIn.isBefore(checkOut)) {
193	            throw new ApiException("INVALID_REQUEST", "Data de saída deve ser depois da entrada", 400);
194	        }
195	    }
196	
197	    private void checkRoomAvailability(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
198	        if (!isRoomAvailable(roomNumber, checkIn, checkOut)) {
199	            throw new ApiException("ROOM_UNAVAILABLE", "Quarto não disponível nas datas solicitadas", 409);
200	        }
201	    }
202	
203	    private RatePlan createRatePlan(String ratePlanCode, Room.RoomType roomType) {
204	        return switch (ratePlanCode) {
205	            case "STANDARD" -> new StandardRatePlan();
206	            case "NON_REFUNDABLE" -> new NonRefundableRatePlan();
207	            case "CORPORATE" -> new CorporateRatePlan();
208	            case "WEEKEND_PACKAGE" -> new WeekendPackageRatePlan();
209	            case "LONG_STAY" -> new LongStayRatePlan();
210	            default -> throw new ApiException("INVALID_REQUEST", "Plano de tarifa inválido", 400);
211	        };
212	    }
213	
214	    public static class ApiException extends RuntimeException {
215	        private final String code;
216	        private final int statusCode;
217	
218	        public ApiException(String code, String message, int statusCode) {
219	            super(message);
220	            this.code = code;
221	            this.statusCode = statusCode;
222	        }
223	
224	        public String getCode() {
225	            return code;
226	        }
227	
228	        public int getStatusCode() {
229	            return statusCode;
230	        }
231	    }
232	}

