 20	public class Main {
 21	    private static final ReservationService reservationService = new ReservationService();
 22	    private static final MessageService messageService = new MessageService();
 23	    private static final ReportService reportService = new ReportService(reservationService);
 24	    private static final DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 25	
 26	    public static void main(String[] args) {
 27	        String port = System.getenv("PORT");
 28	        int portNumber = port != null ? Integer.parseInt(port) : 7070;
 29	
 30	        Javalin app = Javalin.create(config -> {
 31	            config.jsonMapper(createJsonMapper());
 32	        }).start(portNumber);
 33	
 34	        setupRoutes(app);
 35	
 36	        System.out.println("Pousada Maré Alta listening on port " + portNumber);
 37	    }
 38	
 39	    private static void setupRoutes(Javalin app) {
 40	        app.get("/rooms", ctx -> {
 41	            List<Room> rooms = reservationService.getAllRooms();
 42	            List<RoomResponse> responses = rooms.stream()
 43	                .map(room -> new RoomResponse(room.getNumber(), room.getType().toString(),
 44	                                             room.getCapacity(), room.getNightlyRate()))
 45	                .toList();
 46	            ctx.json(responses);
 47	        });
 48	
 49	        app.post("/reservations", ctx -> {
 50	            CreateReservationRequest req = ctx.bodyAsClass(CreateReservationRequest.class);
 51	            validateCreateReservationRequest(req);
 52	
 53	            try {
 54	                Reservation reservation = reservationService.createReservation(
 55	                    req.roomNumber, req.guestName, req.guestEmail, req.guestCpf,
 56	                    req.checkIn, req.checkOut, req.guests, req.ratePlan, req.companyCode
 57	                );
 58	                ctx.status(HttpStatus.CREATED);
 59	                ctx.json(toReservationResponse(reservation));
 60	            } catch (ReservationService.ApiException e) {
 61	                ctx.status(e.getStatusCode());
 62	                ctx.json(new ErrorResponse(e.getCode(), e.getMessage()));
 63	            }
 64	        });
 65	
 66	        app.get("/reservations/{id}", ctx -> {
 67	            try {
 68	                long id = Long.parseLong(ctx.pathParam("id"));
 69	                Reservation reservation = reservationService.getReservation(id);
 70	                ctx.json(toReservationResponse(reservation));
 71	            } catch (ReservationService.ApiException e) {
 72	                ctx.status(e.getStatusCode());
 73	                ctx.json(new ErrorResponse(e.getCode(), e.getMessage()));
 74	            }
 75	        });
 76	
 77	        app.post("/reservations/{id}/confirmation", ctx -> {
 78	            try {
 79	                long id = Long.parseLong(ctx.pathParam("id"));
 80	                Reservation reservation = reservationService.getReservation(id);
 81	
 82	                String body = ctx.body();
 83	                BigDecimal amountPaid = BigDecimal.ZERO;
 84	                if (body != null && !body.isEmpty()) {
 85	                    var map = ctx.bodyAsClass(java.util.Map.class);
 86	                    if (map.containsKey("amountPaid")) {
 87	                        amountPaid = BigDecimal.valueOf(((Number) map.get("amountPaid")).doubleValue());
 88	                    }
 89	                } else {
 90	                    amountPaid = reservation.getTotal();
 91	                }
 92	
 93	                Reservation confirmed = reservationService.confirmReservation(id, amountPaid);
 94	
 95	                Room room = reservationService.getRoom(confirmed.getRoomNumber());
 96	                String emailBody = ReceiptFormatter.formatConfirmationEmail(confirmed, room, confirmed.getGuestName());
 97	                messageService.sendMessage("EMAIL", confirmed.getGuestEmail(),
 98	                                          "Reserva confirmada - Pousada Maré Alta", emailBody);
 99	
100	                ctx.json(toReservationResponse(confirmed));
101	            } catch (ReservationService.ApiException e) {
