118	public class ReceiptFormatter {
119	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
120	    private static final DateTimeFormatter DATE_FORMATTER_API = DateTimeFormatter.ofPattern("yyyy-MM-dd");
121	
122	    public static String formatReceipt(Reservation reservation, Room room) {
123	        Receipt receipt = createReceipt(reservation, room);
124	        return buildReceiptText(receipt);
125	    }
126	
127	    public static String formatConfirmationEmail(Reservation reservation, Room room, String guestName) {
128	        Receipt receipt = createReceipt(reservation, room);
129	
130	        StringBuilder sb = new StringBuilder();
131	        sb.append("Olá, ").append(guestName).append("!\n\n");
132	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
133	        sb.append(buildReceiptText(receipt));
134	        sb.append("\n\nA entrada é a partir das 14h, e a saída, até as 12h.\n");
135	        sb.append("Até breve!");
136	
137	        return sb.toString();
138	    }
139	
140	    public static Receipt createReceipt(Reservation reservation, Room room) {
141	        return new Receipt(
142	            reservation.getId(),
143	            reservation.getGuestName(),
144	            reservation.getGuestCpf(),
145	            reservation.getRoomNumber(),
146	            room.getType().toString(),
147	            reservation.getCheckIn(),
148	            reservation.getCheckOut(),
149	            reservation.getNights(),
150	            reservation.getSubtotal(),
151	            reservation.getDiscount(),
152	            reservation.getTotal()
153	        );
154	    }
155	
156	    private static String buildReceiptText(Receipt receipt) {
157	        StringBuilder sb = new StringBuilder();
158	        sb.append("Comprovante de reserva nº ").append(receipt.getReservationId()).append("\n");
159	        sb.append("Hóspede: ").append(receipt.getGuestName())
160	          .append(" (CPF ").append(formatCpf(receipt.getGuestCpf())).append(")\n");
161	        sb.append("Quarto: ").append(receipt.getRoomNumber())
162	          .append(" (").append(receipt.getRoomType()).append(")\n");
163	        sb.append("Entrada: ").append(formatDate(receipt.getCheckIn()))
164	          .append(" | Saída: ").append(formatDate(receipt.getCheckOut()))
165	          .append(" | ").append(receipt.getNights()).append(receipt.getNights() == 1 ? " diária" : " diárias").append("\n");
166	        sb.append("Diárias: ").append(formatMoney(receipt.getSubtotal())).append("\n");
167	
168	        if (receipt.getDiscount().signum() > 0) {
169	            sb.append("Desconto: ").append(formatMoney(receipt.getDiscount())).append("\n");
170	        }
171	
172	        sb.append("Total: ").append(formatMoney(receipt.getTotal())).append("\n");
173	
174	        return sb.toString();
175	    }
176	
177	    private static String formatDate(LocalDate date) {
178	        return date.format(DATE_FORMATTER);
179	    }
180	
181	    private static String formatMoney(BigDecimal value) {
182	        return String.format("R$ %,.2f", value).replace(",", ".");
183	    }
184	
185	    private static String formatCpf(String cpf) {
186	        if (cpf.length() != 11) {
187	            return cpf;
188	        }
189	        return String.format("%s.%s.%s-%s",
190	            cpf.substring(0, 3),
191	            cpf.substring(3, 6),
192	            cpf.substring(6, 9),
193	            cpf.substring(9, 11));
194	    }
195	}

