 10	public class ReportService {
 11	    private final ReservationService reservationService;
 12	
 13	    public ReportService(ReservationService reservationService) {
 14	        this.reservationService = reservationService;
 15	    }
 16	
 17	    public String getOccupancyReport(String dateStr) {
 18	        try {
 19	            LocalDate date = LocalDate.parse(dateStr, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
 20	            return generateOccupancyReport(date);
 21	        } catch (Exception e) {
 22	            throw new ReservationService.ApiException("INVALID_REQUEST", "Formato de data inválido", 400);
 23	        }
 24	    }
 25	
 26	    public String getRevenueReport(String monthStr) {
 27	        try {
 28	            String[] parts = monthStr.split("-");
 29	            int year = Integer.parseInt(parts[0]);
 30	            int month = Integer.parseInt(parts[1]);
 31	            return generateRevenueReport(year, month);
 32	        } catch (Exception e) {
 33	            throw new ReservationService.ApiException("INVALID_REQUEST", "Formato de mês inválido", 400);
 34	        }
 35	    }
 36	
 37	    private String generateOccupancyReport(LocalDate date) {
 38	        StringBuilder sb = new StringBuilder();
 39	        sb.append("room,type,reservation,check_in,check_out\n");
 40	
 41	        int totalOccupied = 0;
 42	        List<Room> rooms = new ArrayList<>(reservationService.getAllRooms());
 43	        rooms.sort(Comparator.comparingInt(Room::getNumber));
 44	
 45	        for (Room room : rooms) {
 46	            List<Reservation> reservations = reservationService.getReservationsForRoom(room.getNumber(), date);
 47	            for (Reservation reservation : reservations) {
 48	                sb.append(room.getNumber()).append(",");
 49	                sb.append(room.getType()).append(",");
 50	                sb.append(reservation.getId()).append(",");
 51	                sb.append(formatDate(reservation.getCheckIn())).append(",");
 52	                sb.append(formatDate(reservation.getCheckOut())).append("\n");
 53	                totalOccupied++;
 54	            }
 55	        }
 56	
 57	        sb.append("total,").append(totalOccupied).append("/5\n");
 58	        return sb.toString();
 59	    }
 60	
 61	    private String generateRevenueReport(int year, int month) {
 62	        StringBuilder sb = new StringBuilder();
 63	        sb.append("reservation,room,check_in,check_out,status,amount\n");
 64	
 65	        List<Reservation> reservations = reservationService.getReservationsForMonth(year, month);
 66	        reservations.sort((a, b) -> {
 67	            int dateCompare = a.getCheckIn().compareTo(b.getCheckIn());
 68	            if (dateCompare == 0) {
 69	                return Long.compare(a.getId(), b.getId());
 70	            }
 71	            return dateCompare;
 72	        });
 73	
 74	        BigDecimal totalAmount = BigDecimal.ZERO;
 75	
 76	        for (Reservation reservation : reservations) {
 77	            BigDecimal amount = calculateRevenueAmount(reservation);
 78	            sb.append(reservation.getId()).append(",");
 79	            sb.append(reservation.getRoomNumber()).append(",");
 80	            sb.append(formatDate(reservation.getCheckIn())).append(",");
 81	            sb.append(formatDate(reservation.getCheckOut())).append(",");
 82	            sb.append(reservation.getStatus()).append(",");
 83	            sb.append(formatMoney(amount)).append("\n");
 84	            totalAmount = totalAmount.add(amount);
 85	        }
 86	
 87	        sb.append("total,,,,").append(formatMoney(totalAmount)).append("\n");
 88	        return sb.toString();
 89	    }
 90	
 91	    private BigDecimal calculateRevenueAmount(Reservation reservation) {
 92	        if (reservation.getStatus() == Reservation.ReservationStatus.CANCELLED) {
 93	            if (reservation.getRefund() != null) {
 94	                return reservation.getAmountPaid().subtract(reservation.getRefund());
 95	            }
 96	            return BigDecimal.ZERO;
 97	        }
 98	        return reservation.getAmountPaid();
 99	    }
100	
101	    private String formatDate(LocalDate date) {
102	        return date.format(DateTimeFormatter.ofPattern("yyyy-MM-dd"));
103	    }
104	
105	    private String formatMoney(BigDecimal value) {
106	        return String.format("%.2f", value);
107	    }
108	}
